-- Generated by drizzle-kit (the column and the check constraint), then edited by hand to backfill
-- the rows written before this migration. Threat model PE-14, docs/phase-3.md step B0.5 (a).
--
-- arguments_hash = lowercase hex SHA-256 of
--   'aab.job-arguments.v1' || LF || canonicalJson({ agentId, arguments, connectionId, operation,
--     organizationId, policyDecisionId, retrySafe, timeoutMs })
-- (ids are strings, policyDecisionId is null when the column is null, retrySafe is a boolean and
-- timeoutMs a number)
-- where canonicalJson is the one in packages/contracts (keys sorted by UTF-16 code unit, no
-- whitespace, ECMAScript number formatting). The application computes it with
-- hashJobArguments (packages/database/src/job-arguments.ts); this file reproduces the same bytes in SQL for the
-- backfill only. The helper functions are dropped again at the end, so the database keeps no
-- second canonicalizer.
--
-- Exactness: strings, booleans and null print through jsonb's own escaping, which matches
-- JSON.stringify (the same short escapes, \u00XX in lowercase for other control characters,
-- everything else raw). Numbers are reformatted from their exact decimal value with the
-- ECMAScript Number::toString rules. That equals what the worker computes for every number the
-- broker wrote, because the broker only stores numbers JavaScript printed. A number written into
-- the column by hand with more digits than a double holds would hash differently in the worker;
-- such a queued job is then refused as denied (fail closed), never run.
ALTER TABLE "execution_jobs" ADD COLUMN "arguments_hash" text;--> statement-breakpoint
DO $$
BEGIN
  IF current_setting('server_encoding') <> 'UTF8'
     AND EXISTS (SELECT 1 FROM "execution_jobs" WHERE "kind" = 'operation') THEN
    RAISE EXCEPTION '0004_job_arguments_hash: the backfill needs a UTF8 database';
  END IF;
END;
$$;
--> statement-breakpoint
-- Sort key for object members: the key as UTF-16 code units, so keys sort exactly as
-- Array.prototype.sort sorts them (code point order differs for characters above U+FFFF).
CREATE FUNCTION "aab_0004_utf16_units"(input text) RETURNS integer[]
  LANGUAGE sql IMMUTABLE STRICT AS $$
  SELECT coalesce(array_agg(u.unit ORDER BY c.idx, u.half), '{}')
  FROM generate_series(1, char_length(input)) AS c(idx)
  CROSS JOIN LATERAL (SELECT ascii(substr(input, c.idx, 1)) AS code_point) AS p
  CROSS JOIN LATERAL (VALUES
    (1, CASE WHEN p.code_point < 65536 THEN p.code_point
             ELSE 55296 + ((p.code_point - 65536) >> 10) END),
    (2, CASE WHEN p.code_point < 65536 THEN NULL
             ELSE 56320 + ((p.code_point - 65536) & 1023) END)
  ) AS u(half, unit)
  WHERE u.unit IS NOT NULL
$$;
--> statement-breakpoint
-- ECMAScript Number::toString(10) of the exact decimal that jsonb prints (never in exponent form).
CREATE FUNCTION "aab_0004_js_number"(input text) RETURNS text
  LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE
  negative boolean := left(input, 1) = '-';
  unsigned_text text := ltrim(input, '-');
  point integer := position('.' in unsigned_text);
  integer_part text;
  all_digits text;
  digits text;
  n integer; -- the value is 0.digits * 10^n
  k integer;
  body text;
BEGIN
  IF unsigned_text !~ '^[0-9]+(\.[0-9]+)?$' THEN
    RAISE EXCEPTION '0004_job_arguments_hash: unexpected number text';
  END IF;
  IF point = 0 THEN
    integer_part := unsigned_text;
    all_digits := unsigned_text;
  ELSE
    integer_part := left(unsigned_text, point - 1);
    all_digits := integer_part || substr(unsigned_text, point + 1);
  END IF;
  digits := ltrim(all_digits, '0');
  IF digits = '' THEN
    RETURN '0';
  END IF;
  n := char_length(integer_part) - (char_length(all_digits) - char_length(digits));
  digits := rtrim(digits, '0');
  k := char_length(digits);
  IF k <= n AND n <= 21 THEN
    body := digits || repeat('0', n - k);
  ELSIF 0 < n AND n <= 21 THEN
    body := left(digits, n) || '.' || substr(digits, n + 1);
  ELSIF -6 < n AND n <= 0 THEN
    body := '0.' || repeat('0', -n) || digits;
  ELSE
    body := left(digits, 1)
      || CASE WHEN k > 1 THEN '.' || substr(digits, 2) ELSE '' END
      || 'e' || CASE WHEN n - 1 >= 0 THEN '+' ELSE '-' END || abs(n - 1)::text;
  END IF;
  RETURN CASE WHEN negative THEN '-' || body ELSE body END;
END;
$$;
--> statement-breakpoint
CREATE FUNCTION "aab_0004_canonical_json"(input jsonb) RETURNS text
  LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE
  result text;
BEGIN
  CASE jsonb_typeof(input)
    WHEN 'object' THEN
      SELECT '{' || coalesce(string_agg(
               to_jsonb(m.key)::text || ':' || "aab_0004_canonical_json"(m.value), ','
               ORDER BY "aab_0004_utf16_units"(m.key)), '') || '}'
        INTO result
        FROM jsonb_each(input) AS m(key, value);
    WHEN 'array' THEN
      SELECT '[' || coalesce(string_agg(
               "aab_0004_canonical_json"(e.value), ',' ORDER BY e.ordinality), '') || ']'
        INTO result
        FROM jsonb_array_elements(input) WITH ORDINALITY AS e(value, ordinality);
    WHEN 'number' THEN
      result := "aab_0004_js_number"(input::text);
    ELSE
      -- string, boolean, null: jsonb prints these exactly as JSON.stringify does.
      result := input::text;
  END CASE;
  RETURN result;
END;
$$;
--> statement-breakpoint
UPDATE "execution_jobs"
  SET "arguments_hash" = encode(sha256(convert_to(
    'aab.job-arguments.v1' || chr(10) || "aab_0004_canonical_json"(jsonb_build_object(
      'agentId', "agent_id"::text,
      'arguments', "arguments",
      'connectionId', "connection_id"::text,
      'operation', "operation",
      'organizationId', "organization_id"::text,
      'policyDecisionId', "policy_decision_id"::text,
      'retrySafe', "retry_safe",
      'timeoutMs', "timeout_ms")),
    'UTF8')), 'hex')
  WHERE "kind" = 'operation';
--> statement-breakpoint
DROP FUNCTION "aab_0004_canonical_json"(jsonb);
--> statement-breakpoint
DROP FUNCTION "aab_0004_js_number"(text);
--> statement-breakpoint
DROP FUNCTION "aab_0004_utf16_units"(text);
--> statement-breakpoint
-- An operation job must carry a well-formed hash and a login job none; this also proves the
-- backfill reached every operation row.
ALTER TABLE "execution_jobs" ADD CONSTRAINT "execution_jobs_arguments_hash_check" CHECK (("execution_jobs"."kind" = 'operation' and "execution_jobs"."arguments_hash" is not null and "execution_jobs"."arguments_hash" ~ '^[0-9a-f]{64}$') or ("execution_jobs"."kind" = 'login' and "execution_jobs"."arguments_hash" is null));
